\section*{EITHER}
$\left(2 x+2 y \frac{\mathrm{~d} y}{\mathrm{~d} x}\right) y^{2}+\left(x^{2}+y^{2}\right) 2 y \frac{\mathrm{~d} y}{\mathrm{~d} x}=8 x$\\
Note: Award $\boldsymbol{A} 1$ for each of $\left(2 x+2 y \frac{\mathrm{~d} y}{\mathrm{~d} x}\right) y^{2},\left(x^{2}+y^{2}\right) 2 y \frac{\mathrm{~d} y}{\mathrm{~d} x}$ and $8 x$.

\section*{OR}
$$
\begin{aligned}
& x^{2} y^{2}+y^{4}=4 x^{2} \\
& 2 x y^{2}+2 x^{2} y \frac{\mathrm{~d} y}{\mathrm{~d} x}+4 y^{3} \frac{\mathrm{~d} y}{\mathrm{~d} x}=8 x
\end{aligned}
$$

Note: Award $\boldsymbol{A} 1$ for each of $2 x y^{2}+2 x^{2} y \frac{\mathrm{~d} y}{\mathrm{~d} x}, 4 y^{3} \frac{\mathrm{~d} y}{\mathrm{~d} x}$ and $8 x$.

\section*{THEN}
at a local maximum or minimum point, $\frac{\mathrm{d} y}{\mathrm{~d} x}=0$\\
$2 x y^{2}=8 x$\\
$x=0$ or $y^{2}=4(\Rightarrow y= \pm 2)$\\

