question_text:
A continuous random variable $X$ has the probability density function $f$ given by
$$
f(x)=\left\{\begin{array}{cl}
\cfrac{x}{\sqrt{\left(x^2+k\right)^3}} & 0 \leq x \leq 4 \\
0 & \text { otherwise }
\end{array}\right.
$$
where $k \in \mathbb{R}^{+}$.
\begin{parts}
\part[5] Show that $\sqrt{16+k}-\sqrt{k}=\sqrt{k} \sqrt{16+k}$.
\part[2] Find the value of $k$.
\end{parts}

explanation:
(a) recognition of the need to integrate $\frac{x}{\sqrt{\left(x^{2}+k\right)^{3}}}$\\
$\int \frac{x}{\sqrt{\left(x^{2}+k\right)^{3}}} \mathrm{~d} x(=1)$

\section*{EITHER}
$u=x^{2}+k \Rightarrow \frac{\mathrm{~d} u}{\mathrm{~d} x}=2 x$ (or equivalent)\\
$\int \frac{x}{\sqrt{\left(x^{2}+k\right)^{3}}} \mathrm{~d} x=\frac{1}{2} \int u^{-\frac{3}{2}} \mathrm{~d} u$\\
$=-u^{-\frac{1}{2}}(+c)\left(=-\left(x^{2}+k\right)^{-\frac{1}{2}}(+c)\right)$

\section*{Question 7 continued}
OR


\begin{align*}
& \int \frac{x}{\sqrt{\left(x^{2}+k\right)^{3}}} \mathrm{~d} x=\frac{1}{2} \int \frac{2 x}{\sqrt{\left(x^{2}+k\right)^{3}}} \mathrm{~d} x  \tag{A1}\\
& =-\left(x^{2}+k\right)^{-\frac{1}{2}}(+c) \tag{A1}
\end{align*}


\section*{THEN}
attempt to use correct limits for their integrand and set equal to 1

$$
\begin{aligned}
& {\left[-u^{-\frac{1}{2}}\right]_{k}^{16+k}=1 \text { OR }\left[-\left(x^{2}+k\right)^{-\frac{1}{2}}\right]_{0}^{4}=1} \\
& -(16+k)^{-\frac{1}{2}}+k^{-\frac{1}{2}}=1\left(\Rightarrow \frac{1}{\sqrt{k}}-\frac{1}{\sqrt{16+k}}=1\right) \\
& \sqrt{16+k}-\sqrt{k}=\sqrt{k} \sqrt{16+k}
\end{aligned}
$$

\\
(b) attempt to solve $\sqrt{16+k}-\sqrt{k}=\sqrt{k} \sqrt{16+k}$\\
(M1)\\
$k=0.645038 \ldots$\\
$=0.645$\\
A1\\
\\
Total \\

question_text:
Consider the complex numbers $z=2\left(\cos \cfrac{\pi}{5}+\mathrm{i} \sin \cfrac{\pi}{5}\right)$ and $w=8\left(\cos \cfrac{2 k \pi}{5}-\mathrm{i} \sin \cfrac{2 k \pi}{5}\right)$, where $k \in \mathbb{Z}^{+}$.
